<template><div class="graph-wrap"><svg ref="svg" role="img" aria-label="Interactive research topic network"></svg><p class="hint">Drag nodes to explore research connections · 拖曳節點探索研究關聯</p></div></template>
<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue'
import * as d3 from 'd3'
import { research } from '../data'
const svg=ref(null);let simulation,observer
function draw(){if(!svg.value)return;const el=svg.value,w=el.clientWidth||650,h=340;d3.select(el).selectAll('*').remove();const nodes=[{id:'CGV',title:'CGV Lab',color:'#1b557b'},...research.map(x=>({...x}))];const links=research.map(x=>({source:'CGV',target:x.id})).concat([{source:'CG',target:'DT'},{source:'VA',target:'RL'},{source:'VA',target:'HAI'},{source:'DT',target:'HAI'}]);const s=d3.select(el).attr('viewBox',`0 0 ${w} ${h}`);simulation?.stop();simulation=d3.forceSimulation(nodes).force('link',d3.forceLink(links).id(d=>d.id).distance(105)).force('charge',d3.forceManyBody().strength(-380)).force('center',d3.forceCenter(w/2,h/2)).force('collision',d3.forceCollide(40));const line=s.append('g').selectAll('line').data(links).join('line').attr('stroke','#54718e').attr('stroke-opacity',.65).attr('stroke-width',1.5);const group=s.append('g').selectAll('g').data(nodes).join('g').style('cursor','grab').call(d3.drag().on('start',(event,d)=>{if(!event.active)simulation.alphaTarget(.3).restart();d.fx=d.x;d.fy=d.y}).on('drag',(event,d)=>{d.fx=event.x;d.fy=event.y}).on('end',(event,d)=>{if(!event.active)simulation.alphaTarget(0);d.fx=null;d.fy=null}));group.append('circle').attr('r',d=>d.id==='CGV'?34:25).attr('fill',d=>d.color).attr('fill-opacity',.16).attr('stroke',d=>d.color).attr('stroke-width',2);group.append('text').text(d=>d.id).attr('fill','#193e60').attr('text-anchor','middle').attr('dominant-baseline','middle').attr('font-size',d=>d.id==='CGV'?14:12).attr('font-weight',700);group.append('title').text(d=>d.title);simulation.on('tick',()=>{nodes.forEach(d=>{d.x=Math.max(40,Math.min(w-40,d.x));d.y=Math.max(40,Math.min(h-40,d.y))});line.attr('x1',d=>d.source.x).attr('y1',d=>d.source.y).attr('x2',d=>d.target.x).attr('y2',d=>d.target.y);group.attr('transform',d=>`translate(${d.x},${d.y})`)})}
onMounted(()=>{observer=new ResizeObserver(draw);observer.observe(svg.value)});onBeforeUnmount(()=>{observer?.disconnect();simulation?.stop()})
</script>
